const id = 'record-structured-1';
const current = await client.items.find<Schema.AnyModel>(id, { nested: true });
const body = JSON.parse(JSON.stringify(current.body));
const english = body.en;
const greeting = english.document.children[0].children[0];
if (greeting.type !== 'span' || greeting.value !== 'Hello reader' || JSON.stringify(greeting.marks) !== JSON.stringify(['strong'])) throw new Error('Unexpected greeting span');
greeting.value = 'Welcome reader';
const imageNode = english.document.children.find((node) => node.type === 'block');
if (!imageNode || imageNode.item.id !== 'block-structured-1') throw new Error('Unexpected image block');
imageNode.item.attributes.caption = 'Summer portrait';
english.document.children.push({ type: 'paragraph', children: [{ type: 'span', value: 'See you soon.' }] });
await client.items.update(id, { body });
const saved = await client.items.find<Schema.AnyModel>(id, { nested: true });
const savedEn = saved.body.en;
const savedIt = saved.body.it;
const savedGreeting = savedEn.document.children[0].children[0];
const savedImage = savedEn.document.children.find((node) => node.type === 'block');
const savedLast = savedEn.document.children[savedEn.document.children.length - 1];
console.log(JSON.stringify({
  status: saved.meta.status,
  greeting: savedGreeting,
  image: savedImage && { id: savedImage.item.id, caption: savedImage.item.attributes.caption, image: savedImage.item.attributes.image },
  last: savedLast,
  italian: savedIt,
  title: saved.title,
  untouched: saved.untouched
}));

const record = await client.items.find<Schema.SmokeArticle>('record-structured-3', { nested: true });
if (!record.body?.en || !record.body.it) throw new Error('Expected English and Italian body values');

const originalEnglish = record.body.en;
const editedText = serialize(originalEnglish).replace('Hello reader', 'Welcome reader');
const parsedEnglish = parse(editedText, originalEnglish);
const editedEnglish = mapNodes(parsedEnglish, (node) => {
  if (isBlockWithItemOfType('image-model', node)) {
    return { ...node, item: buildBlockRecord<Schema.SmokeImage>({ id: node.item.id, caption: 'Summer portrait' }) };
  }
  return node;
});
editedEnglish.document.children.push({
  type: 'paragraph',
  children: [{ type: 'span', value: 'See you soon.' }],
});

await client.items.update<Schema.SmokeArticle>(record.id, {
  body: { ...record.body, en: editedEnglish },
});
console.log(JSON.stringify({ updated: record.id }));

